from pathlib import Path

import pytest
from fastapi.testclient import TestClient

from app.api.main import create_app
from app.config.settings import Settings
from app.services.tasks import TaskService
from tests.integration.test_mvp import EvidenceDouble


@pytest.fixture
def client(tmp_path):
    settings = Settings(
        repository_root=Path(__file__).parents[2] / "test_fixtures" / "repair_repository", data_dir=tmp_path / "data"
    )
    service = TaskService(settings, runner=EvidenceDouble())
    with TestClient(create_app(service=service)) as client:
        yield client, settings, service
    service.close()


def create(client, settings):
    response = client.post(
        "/api/tasks",
        json={
            "issue_description": "expired returns 500",
            "repository_path": str(settings.repository_root),
        },
    )
    assert response.status_code == 202
    return response.json()["task_id"]


def test_api_create_logs_diff_reject(client):
    api, settings, _ = client
    task_id = create(api, settings)
    state = api.get(f"/api/tasks/{task_id}").json()
    assert state["execution_status"] == "awaiting_approval"
    assert api.get(f"/api/tasks/{task_id}/events").json()["events"]
    diff = api.get(f"/api/tasks/{task_id}/diff").json()
    assert diff["matches_recorded"]
    assert (
        api.post(
            f"/api/tasks/{task_id}/approve", json={"diff_digest": diff["diff_digest"]}
        ).status_code
        == 409
    )
    assert (
        api.post(f"/api/tasks/{task_id}/reject", json={"diff_digest": diff["diff_digest"]}).json()[
            "execution_status"
        ]
        == "rejected"
    )
    assert api.post(f"/api/tasks/{task_id}/resume").status_code == 409


def test_approval_detects_tamper(client):
    api, settings, service = client
    task_id = create(api, settings)
    state = service.get(task_id)
    path = Path(state["workspace_path"]) / "auth.py"
    path.write_text(path.read_text() + "\n# changed after review\n")
    assert (
        api.post(
            f"/api/tasks/{task_id}/reject", json={"diff_digest": state["diff_digest"]}
        ).status_code
        == 409
    )


def test_invalid_paths_and_browser_origin(client):
    api, settings, _ = client
    assert api.get("/api/tasks/no-such-task").status_code == 404
    assert (
        api.post(
            "/api/tasks",
            json={
                "issue_description": "bad repository",
                "repository_path": str(settings.repository_root.parent),
            },
        ).status_code
        == 400
    )
    assert (
        api.post(
            "/api/tasks",
            headers={"Origin": "https://evil.example"},
            json={
                "issue_description": "expired returns 500",
                "repository_path": str(settings.repository_root),
            },
        ).status_code
        == 403
    )
    assert api.get("/api/tasks/no-such-task", headers={"Host": "evil.example"}).status_code == 403

from pathlib import Path

from langgraph.checkpoint.memory import InMemorySaver
from langgraph.types import Command

from app.agents.model import MockModel
from app.config.settings import Settings
from app.graph.workflow import build_graph
from app.models.schemas import Edit, Patch, Review, TaskRequest, TestResult
from app.services.tasks import TaskService
from tests.integration.test_mvp import EvidenceDouble, initial


class RetryModel(MockModel):
    def __init__(self):
        self.attempt = 0

    def generate(self, schema, payload):
        if schema is Patch:
            self.attempt += 1
            if self.attempt == 1:
                patch, stats = super().generate(schema, payload)
                patch.edits[0].new = 'status_code=402, detail="Token expired"'
                return patch, stats
            return Patch(
                rationale="Use test feedback",
                edits=[Edit(path="auth.py", old="status_code=402", new="status_code=401")],
            ), {"calls": 0, "input_tokens": 0, "output_tokens": 0}
        return super().generate(schema, payload)


class SequenceRunner:
    def __init__(self, statuses):
        self.statuses = iter(statuses)

    def run(self, workspace):
        status = next(self.statuses)
        return TestResult(
            status=status,
            exit_code=0 if status == "passed" else 1,
            passed=int(status == "passed"),
            failed=int(status == "failed"),
            evidence="test_double",
            stderr="explicit runner double",
        )


def test_test_feedback_retries_once(tmp_path):
    state = initial(tmp_path)
    graph = build_graph(
        Settings(), RetryModel(), SequenceRunner(["failed", "passed"]), InMemorySaver()
    )
    result = graph.invoke(state, {"configurable": {"thread_id": state["thread_id"]}})
    assert result["execution_status"] == "awaiting_approval"
    assert result["retry_count"] == 1
    assert result["attempts"] == 2


def test_budget_terminates(tmp_path):
    state = initial(tmp_path)
    graph = build_graph(
        Settings(max_retries=1), RetryModel(), SequenceRunner(["failed", "failed"]), InMemorySaver()
    )
    result = graph.invoke(state, {"configurable": {"thread_id": state["thread_id"]}})
    assert result["execution_status"] == "failed"
    assert result["attempts"] == 2
    assert "budget exhausted" in result["error"]


def test_review_feedback_routes_to_coder(tmp_path):
    class ReviewRetry(RetryModel):
        def generate(self, schema, payload):
            if schema is Review:
                return Review(approved=self.attempt == 2, summary="fixture review", concerns=[]), {
                    "calls": 0,
                    "input_tokens": 0,
                    "output_tokens": 0,
                }
            return super().generate(schema, payload)

    state = initial(tmp_path)
    graph = build_graph(
        Settings(), ReviewRetry(), SequenceRunner(["passed", "passed"]), InMemorySaver()
    )
    result = graph.invoke(state, {"configurable": {"thread_id": state["thread_id"]}})
    assert result["retry_count"] == 1
    assert len(result["review_results"]) == 2


def test_human_reject(tmp_path):
    state = initial(tmp_path)
    graph = build_graph(Settings(), MockModel(), EvidenceDouble(), InMemorySaver())
    config = {"configurable": {"thread_id": state["thread_id"]}}
    result = graph.invoke(state, config)
    result = graph.invoke(
        Command(resume={"approved": False, "diff_digest": result["diff_digest"]}), config
    )
    assert result["execution_status"] == "rejected"


def settings(tmp_path):
    return Settings(
        repository_root=Path(__file__).parents[2] / "test_fixtures" / "repair_repository", data_dir=tmp_path / "data"
    )


def test_sqlite_restart_and_blocked_resume(tmp_path):
    config = settings(tmp_path)
    service = TaskService(config, runner=SequenceRunner(["unavailable"]))
    task = service.create(
        TaskRequest(
            repository_path=str(config.repository_root),
            issue_description="expired token returns 500",
        )
    )
    first = service.run(task["task_id"])
    assert first["execution_status"] == "blocked"
    service.close()
    service = TaskService(config, runner=EvidenceDouble())
    try:
        second = service.run(task["task_id"])
        assert second["execution_status"] == "awaiting_approval"
        assert second["attempts"] == 1
        assert second["thread_id"] != second["task_id"]
        assert len(second["test_results"]) == 2
        # A test double cannot authorize an external operation.
        import pytest

        with pytest.raises(ValueError, match="real Docker"):
            service.decide(task["task_id"], True, second["diff_digest"])
        rejected = service.decide(task["task_id"], False, second["diff_digest"])
        assert rejected["execution_status"] == "rejected"
    finally:
        service.close()


def test_resume_failure_still_tests_each_new_attempt(tmp_path):
    config = settings(tmp_path)
    service = TaskService(
        config, model=RetryModel(), runner=SequenceRunner(["unavailable", "failed", "passed"])
    )
    try:
        task = service.create(
            TaskRequest(
                repository_path=str(config.repository_root),
                issue_description="expired returns 500 expected 401",
            )
        )
        assert service.run(task["task_id"])["execution_status"] == "blocked"
        result = service.run(task["task_id"])
        assert result["execution_status"] == "awaiting_approval"
        assert result["attempts"] == 2 and len(result["test_results"]) == 3
        assert [t["attempt"] for t in result["test_results"]] == [1, 1, 2]
    finally:
        service.close()

import json
from pathlib import Path

from app.config.settings import Settings
from app.evaluation.runner import run_evaluation
from app.models.schemas import TestResult


def test_already_passing_baseline_is_not_counted_as_a_repair(tmp_path: Path, monkeypatch):
    class PassingBaselineDouble:
        def __init__(self, settings):
            pass

        def run(self, workspace):
            return TestResult(status="passed", passed=1, evidence="test_double")

    monkeypatch.setattr("app.evaluation.runner.DockerRunner", PassingBaselineDouble)
    source = Path(__file__).parents[2] / "test_fixtures" / "repair_repository"
    report = run_evaluation(
        Settings(repository_root=source, data_dir=tmp_path / "data"), source, tmp_path / "report"
    )
    records = [
        json.loads(line)
        for line in (tmp_path / "report/runs.jsonl").read_text(encoding="utf-8").splitlines()
    ]
    assert len(records) == 9
    assert all(record["execution_status"] == "invalid_case" for record in records)
    assert all(record["task_id"] is None for record in records)
    for mode in report["modes"].values():
        assert mode["bug_fix_success_rate"] is None
        assert mode["repair_evaluated"] == 0
        assert mode["invalid_case_runs"] == 3
